 void Awake(){Application.runInBackground=true;Application.targetFrameRate=60;QualitySettings.vSyncCount=0;Directory.CreateDirectory(Out);Log("loaded");StartCoroutine(Safe(Run()));}
 void Log(string s){File.AppendAllText(Path.Combine(Out,"progress.log"),DateTime.UtcNow.ToString("o")+" "+s+"\n");}
 IEnumerator Safe(IEnumerator r){while(true){object v;try{if(!r.MoveNext())yield break;v=r.Current;}catch(Exception e){Log("FAILED "+e);File.WriteAllText(Path.Combine(Out,"failed.txt"),e.ToString());Application.Quit();yield break;}yield return v;}}
 IEnumerator Frames(int n){for(int i=0;i<n;i++)yield return null;}
 static JSONNode J(object o){if(o==null)return new JSONData("");if(o is bool)return new JSONData((bool)o);if(o is float)return new JSONData((float)o);if(o is int)return new JSONData((int)o);if(o is Vector3){var a=new JSONArray();var v=(Vector3)o;a.Add(new JSONData(v.x));a.Add(new JSONData(v.y));a.Add(new JSONData(v.z));return a;}if(o is Quaternion){var a=new JSONArray();var q=(Quaternion)o;a.Add(J(q.x));a.Add(J(q.y));a.Add(J(q.z));a.Add(J(q.w));return a;}if(o is Matrix4x4){var a=new JSONArray();var m=(Matrix4x4)o;for(int r=0;r<4;r++)for(int c=0;c<4;c++)a.Add(J(m[r,c]));return a;}return new JSONData(o.ToString());}
 static object Get(object o,string k){var t=o.GetType();var p=t.GetProperty(k);if(p!=null)return p.GetValue(o,null);var f=t.GetField(k);return f==null?null:f.GetValue(o);}
 static JSONClass Fields(object o,params string[] keys){var j=new JSONClass();foreach(var k in keys){try{j[k]=J(Get(o,k));}catch(Exception e){j[k]=J("ERROR "+e.Message);}}return j;}
