 void Buf(string prefix,string name,ComputeBuffer b,JSONClass j){if(b==null){j[name]=J("unavailable");return;}var vs=new Vector3[b.count];b.GetData(vs);int n=Math.Min(skin.dazMesh.numUVVertices,b.count);VecFile(prefix+"-"+name+".f32",vs,n);var d=new JSONClass();d["count"]=J(n);d["stride"]=J(b.stride);d["file"]=J(prefix+"-"+name+".f32");j[name]=d;}
 void Hold(){if(!holding)return;foreach(var b in bones){b.transform.localPosition=pos[b];b.transform.localRotation=rot[b];b.transform.localScale=scale[b];Vector3 v;if(angles.TryGetValue(b.id,out v))b.transform.localRotation=rot[b]*Quaternion2Angles.EulerToQuaternion(v,b.rotationOrder);}}
