 void Capture(string name){var j=new JSONClass();j["frame"]=J(Time.frameCount);j["time"]=J(Time.time);j["person_uid"]=J(person.uid);j["preset"]=J(Preset);j["core_pose_auto"]=J(core);j["dynamics"]=J(false);j["extra_plugins"]=J("none; isolated readout/pose harness only");j["matrix_layout"]=J("row-major flattened Unity column-vector matrix; Unity metres");j["skin"]=Fields(skin,"name","skinMethod","useGeneralWeights","hasGeneralWeights","useSmoothing","allowPostSkinMorph","useAsynchronousThreadedSkinning","useMultithreadedSkinning","delayDisplayOneFrame");j["skin_path"]=J(PathOf(skin.transform));j["skin_world"]=J(skin.transform.localToWorldMatrix);var ba=new JSONArray();foreach(var b in bones){var d=Fields(b,"id","rotationOrder","useUnityEulerOrientation","worldPosition","worldOrientation","morphedWorldPosition","morphedWorldOrientation","startingLocalPosition","startingLocalRotation","rotationMorphsEnabled","jointRotationDisabled","disableMorph");d["path"]=J(PathOf(b.transform));d["localPosition"]=J(b.transform.localPosition);d["localRotation"]=J(b.transform.localRotation);d["localScale"]=J(b.transform.localScale);d["worldMatrix"]=J(b.transform.localToWorldMatrix);d["morphedBind"]=J(b.morphedLocalToWorldMatrix);d["actualAnglesDegrees"]=J(b.GetAnglesDegrees());foreach(var key in new[]{"morphOffsets","morphOrientationOffsets","morphRotations"}){var dict=Get(b,key) as IDictionary;var dj=new JSONClass();if(dict!=null)foreach(DictionaryEntry e in dict)dj[e.Key.ToString()]=J(e.Value);d[key]=dj;}ba.Add(d);}j["bones"]=ba;var ma=new JSONArray();foreach(var bank in banks){foreach(var m in bank.morphs){if(name!="loaded-appearance"&&!m.active&&!m.isDriven&&Math.Abs(m.morphValue)<1e-8&&Math.Abs(m.appliedValue)<1e-8)continue;var d=Fields(m,"uid","morphName","displayName","morphValue","appliedValue","visible","active","disable","isPoseControl","isDriven","drivenBy","hasFormulas","hasBoneModificationFormulas","hasBoneRotationFormulas","metaLoadPath","metaJSONFile","packageUid");d["bank"]=J(PathOf(bank.transform));ma.Add(d);}}j["morphs"]=ma;j["morph_catalog"]=J("loaded-appearance.json");j["omitted_morphs"]=J("inactive, not driven, both current/applied zero; catalog records metadata");var da=new JSONArray();foreach(var d in drivers){var x=Fields(d,"morph1Name","currentMorph1Value","morphRawValue","enabled","updateEnabled","isOn","angleLow","angleHigh","angleAxis","angleAxis1","angleAxis2","multiplier","currentAxisAngle","currentAxisAngle1","currentAxisAngle2");x["type"]=J(d.GetType().Name);x["path"]=J(PathOf(d.transform));da.Add(x);}j["drivers"]=da;var bk=new JSONArray();foreach(var bank in banks)bk.Add(Fields(bank,"name","enableMCMMorphs"));j["banks"]=bk;Buf(name,"raw",skin.rawVertsBuffer,j);Buf(name,"smoothed",skin.smoothedVertsBuffer,j);VecFile(name+"-legacy-morphed.f32",skin.dazMesh.morphedUVVertices,skin.dazMesh.numUVVertices);var cr=person.GetComponentsInChildren<DAZCharacterRun>(true).First(x=>x.skin==skin);var input=cr.snappedMorphedUVVertices;if(input!=null){VecFile(name+"-morphed.f32",input,input.Length);j["morphed_input_source"]=J("DAZCharacterRun.snappedMorphedUVVertices before skin");}else j["morphed_input_source"]=J("not available before diagnostic snap enabled");Save(name+".json",j);Log("captured "+name);}
 void ExportDeltas(){var catalog=new JSONArray();int index=0;foreach(var bank in banks)foreach(var m in bank.morphs){if(Math.Abs(m.morphValue)<1e-8&&Math.Abs(m.appliedValue)<1e-8&&!m.isDriven)continue;m.LoadDeltas();var j=Fields(m,"uid","morphName","morphValue","appliedValue","drivenBy","metaLoadPath","metaJSONFile","deltasLoadPath","formulasString");j["bank"]=J(PathOf(bank.transform));j["connected_mesh"]=Fields(bank.connectedMesh,"name","numBaseVertices","numUVVertices");string file="morph-deltas-"+(index++)+".bin";using(var w=new BinaryWriter(File.Create(Path.Combine(Out,file)))){if(m.deltas!=null)foreach(var v in m.deltas){w.Write(v.vertex);w.Write(v.delta.x);w.Write(v.delta.y);w.Write(v.delta.z);}}j["deltas_file"]=J(file);catalog.Add(j);}Save("active-delta-catalog.json",catalog);}
 IEnumerator Run(){float start=Time.realtimeSinceStartup;while(SuperController.singleton==null){if(Time.realtimeSinceStartup-start>180)throw new Exception("SuperController startup timeout");yield return null;}yield return new WaitForSecondsRealtime(12);Log("loading default create scene");SuperController.singleton.LoadForEdit(@"F:\Virt A Mate\Saves\scene\MeshedVR\default.json");yield return new WaitForSecondsRealtime(5);while(SuperController.singleton.isLoading)yield return null;person=SuperController.singleton.GetAtomByUid("Person");if(person==null)throw new Exception("default Person missing");foreach(var pm in UnityEngine.Object.FindObjectsOfType<MVRPluginManager>())pm.RemoveAllPlugins();Log("cleared runtime scene/session plugins; loading appearance");var managers=person.GetComponentsInChildren<MeshVR.PresetManager>(true);foreach(var manager in managers)Log("preset manager "+manager.name+" folder="+manager.storeFolderName+" appearance="+manager.includeAppearance);var appearance=managers.First(m=>m.storeFolderName=="Appearance");appearance.LoadPresetFromJSON(JSON.Parse(File.ReadAllText(Preset)).AsObject,false);yield return new WaitForSecondsRealtime(15);while(SuperController.singleton.isLoading)yield return null;foreach(var pm in UnityEngine.Object.FindObjectsOfType<MVRPluginManager>())pm.RemoveAllPlugins();var selector=person.GetComponentInChildren<DAZCharacterSelector>();skin=selector.selectedCharacter.skin;if(!skin.wasInit)throw new Exception("skin not initialized");bones=selector.selectedCharacter.rootBonesForSkinning.dazBones; banks=new[]{selector.morphBank1,selector.morphBank2,selector.morphBank3}.Where(x=>x!=null).Distinct().ToArray();drivers=person.GetComponentsInChildren<SetDAZMorph>(true);if(!banks.SelectMany(b=>b.morphs).Any(m=>m.morphName.Contains("a07 - Body")&&Math.Abs(m.morphValue-1)<0.0001))throw new Exception("Appearance identity mismatch: a07 body is not 1");Capture("loaded-appearance");var ass=new JSONArray();foreach(var a in AppDomain.CurrentDomain.GetAssemblies())ass.Add(J(a.GetName().Name));Save("assemblies.json",ass);
 foreach(var cr in person.GetComponentsInChildren<DAZCharacterRun>(true)){cr.WaitForRunTask();cr.useThreading=false;cr.doSnap=true;}foreach(var ctrl in person.GetComponentsInChildren<FreeControllerV3>(true))ctrl.enabled=false;SuperController.singleton.SetFreezeAnimation(true);person.SetFreezePhysics(true);foreach(var p in person.GetComponentsInChildren<DAZPhysicsMesh>(true))p.on=false;foreach(var rb in person.GetComponentsInChildren<Rigidbody>(true)){rb.isKinematic=true;rb.useGravity=false;}skin.allowPostSkinMorph=false;skin.useAsynchronousThreadedSkinning=false;skin.useMultithreadedSkinning=false;
 foreach(var b in bones){pos[b]=b.startingLocalPosition;rot[b]=b.startingLocalRotation;scale[b]=b.transform.localScale;}
 holding=true;Hold();
 var poses=new List<KeyValuePair<string,float[]>>();poses.Add(new KeyValuePair<string,float[]>("standing",new float[]{0,0,0,0}));foreach(float a in new[]{30f,60f,90f,110f})poses.Add(new KeyValuePair<string,float[]>("hip"+a,new[]{a,0,a,0}));foreach(float a in new[]{30f,60f,90f,120f})poses.Add(new KeyValuePair<string,float[]>("knee"+a,new[]{0f,a,0f,a}));poses.Add(new KeyValuePair<string,float[]>("seated",new[]{90f,90f,90f,90f}));poses.Add(new KeyValuePair<string,float[]>("deep",new[]{110f,120f,110f,120f}));poses.Add(new KeyValuePair<string,float[]>("asymmetric",new[]{90f,90f,30f,60f}));
 var originals=drivers.ToDictionary(d=>d,d=>d.enabled);var updates=drivers.ToDictionary(d=>d,d=>Get(d,"updateEnabled"));
 foreach(bool mode in new[]{false,true}){core=mode;foreach(var d in drivers){d.enabled=mode&&originals[d];var f=d.GetType().GetField("updateEnabled");if(f!=null)f.SetValue(d,mode&&(updates[d] is bool?(bool)updates[d]:true));if(!mode)d.morphRawValue=0;} // Shape MCM remains in both modes to preserve appearance; report explicitly.
 foreach(var p in poses){angles.Clear();angles["lThigh"]=new Vector3(-p.Value[0],0,0);angles["rThigh"]=new Vector3(-p.Value[2],0,0);angles["lShin"]=new Vector3(p.Value[1],0,0);angles["rShin"]=new Vector3(p.Value[3],0,0);for(int k=0;k<20;k++){Hold();yield return null;}yield return new WaitForEndOfFrame();Capture((mode?"core-on-":"core-off-")+p.Key);if(!mode&&p.Key=="standing")ExportDeltas();yield return new WaitForEndOfFrame();Capture((mode?"core-on-":"core-off-")+p.Key+"-repeat");}}

 // True single-morph intervention: first capture the frozen all-driver state,
 // then change only Bend Fix, and restore. Every coefficient is recorded.
 angles.Clear();angles["lThigh"]=new Vector3(-90,0,0);angles["rThigh"]=new Vector3(-90,0,0);angles["lShin"]=new Vector3(90,0,0);angles["rShin"]=new Vector3(90,0,0);
 for(int k=0;k<20;k++)yield return null;
 heldMorphs=banks.SelectMany(b=>b.morphs).Distinct().ToDictionary(m=>m,m=>m.morphValue);
 foreach(var d in drivers){d.enabled=false;var f=d.GetType().GetField("updateEnabled");if(f!=null)f.SetValue(d,false);}
 foreach(var bank in banks)bank.enableMCMMorphs=false;
 for(int k=0;k<20;k++)yield return null;yield return new WaitForEndOfFrame();Capture("ablation-frozen-baseline");
 var bend=heldMorphs.Keys.Where(m=>m.uid=="Glute Bend Fix").ToArray();if(bend.Length!=1)throw new Exception("Single Bend Fix identity ambiguous: "+bend.Length);float previous=heldMorphs[bend[0]];heldMorphs[bend[0]]=0;
 for(int k=0;k<20;k++)yield return null;yield return new WaitForEndOfFrame();Capture("ablation-bend-zero");heldMorphs[bend[0]]=previous;
 for(int k=0;k<20;k++)yield return null;yield return new WaitForEndOfFrame();Capture("ablation-restored");
 File.WriteAllText(Path.Combine(Out,"complete.txt"),"pose auto off/on captured; MCM preserved in both; inspect transform equality and stability before acceptance");Log("complete");Application.Quit();}
